CREATE TABLE Region (ID INT PRIMARY KEY, Nombre VARCHAR(100) NOT NULL, Superficie INT NOT NULL);
CREATE TABLE Provincia (ID INT PRIMARY KEY, Nombre VARCHAR(100) NOT NULL, Superficie INT NOT NULL, ID_Region INT NOT NULL, FOREIGN KEY (ID_Region) REFERENCES Region(ID) ON UPDATE CASCADE ON DELETE NO ACTION);
CREATE TABLE Comuna (ID INT PRIMARY KEY, Nombre VARCHAR(100) NOT NULL, Superficie INT NOT NULL, ID_Provincia INT NOT NULL, FOREIGN KEY (ID_Provincia) REFERENCES Provincia(ID) ON UPDATE CASCADE ON DELETE NO ACTION);
CREATE TABLE Empresa (RUT VARCHAR(11) PRIMARY KEY NOT NULL, Nombre VARCHAR(30) NOT NULL, Giro VARCHAR(30));
CREATE TABLE Emprendedor (RUN VARCHAR(10) PRIMARY KEY NOT NULL, Nombre VARCHAR(30) NOT NULL, Apellido VARCHAR(30) NOT NULL, FechaNac DATE NOT NULL, Passwd TEXT NOT NULL UNIQUE, Web VARCHAR(255), Empresa_id VARCHAR(11), FOREIGN KEY (Empresa_id) REFERENCES Empresa(RUT) ON UPDATE CASCADE ON DELETE NO ACTION);
CREATE TABLE Cliente (RUN VARCHAR(10) PRIMARY KEY NOT NULL, Nombre VARCHAR(30) NOT NULL, Apellido VARCHAR(30) NOT NULL, FechaNac DATE NOT NULL, Passwd TEXT NOT NULL UNIQUE);
CREATE TABLE Calificacion (ID INT PRIMARY KEY NOT NULL, Puntaje SMALLINT NOT NULL, Comentario TEXT);
CREATE TABLE Direccion (CodPostal INT PRIMARY KEY NOT NULL, Calle VARCHAR(40) NOT NULL, Numero INT NOT NULL, Pasaje VARCHAR(30), Sector VARCHAR(30), Comuna_id INT NOT NULL, Emprendedor_id VARCHAR(10), Cliente_id VARCHAR(10), FOREIGN KEY (Comuna_id) REFERENCES Comuna(ID) ON UPDATE CASCADE ON DELETE NO ACTION);
CREATE TABLE Telefono (Telefono INT PRIMARY KEY NOT NULL, Empresa_id VARCHAR(11), Emprendedor_id VARCHAR(10), Cliente_id VARCHAR(10));
CREATE TABLE Correo (Correo VARCHAR(255) PRIMARY KEY NOT NULL, Empresa_id VARCHAR(11), Emprendedor_id VARCHAR(10), Cliente_id VARCHAR(10));
CREATE TABLE Envio (Seguimiento INT PRIMARY KEY NOT NULL, FechaSalida DATE NOT NULL DEFAULT CURRENT_DATE, FechaLlegada DATE NOT NULL, Empresa VARCHAR(30) NOT NULL, Valor MONEY NOT NULL, Peso DECIMAL(4,1), Altura DECIMAL(4,1), Ancho DECIMAL(4,1), Fondo DECIMAL(4,1));
CREATE TABLE Venta (ID INT PRIMARY KEY NOT NULL, ValorBruto INT NOT NULL, IVA DECIMAL(5,2) NOT NULL, Descuento INT, Total INT NOT NULL, Descripcion TEXT, Despacho INT, Estado VARCHAR(30), FOREIGN KEY (Despacho) REFERENCES Envio(Seguimiento) ON UPDATE CASCADE ON DELETE NO ACTION);
CREATE TABLE MedioPago (ID INT PRIMARY KEY NOT NULL, Tipo VARCHAR(30) NOT NULL, Marca VARCHAR(30) NOT NULL, Digitos SMALLINT NOT NULL);
CREATE TABLE Oferta (ID INT PRIMARY KEY NOT NULL, Precio INT NOT NULL);
CREATE TABLE Categoría (ID INT PRIMARY KEY NOT NULL, Nombre VARCHAR(50) NOT NULL, Categoria_id INT);
CREATE TABLE Producto (ID INT PRIMARY KEY NOT NULL, Nombre VARCHAR(50) NOT NULL, Restriccion VARCHAR(30), Descripción JSON, Categoria_id INT NOT NULL, Activo BOOLEAN DEFAULT TRUE);
CREATE TABLE Servicio (ID INT PRIMARY KEY NOT NULL, Nombre VARCHAR(50) NOT NULL, Restriccion VARCHAR(30), Duracion TIMESTAMP, Precio INT NOT NULL, Descripcion JSON, Categoria_id INT NOT NULL, Activo BOOLEAN DEFAULT TRUE);
CREATE TABLE Caracteristicas (ID INT PRIMARY KEY NOT NULL, Peso DECIMAL(4,2) NOT NULL, Color VARCHAR(20) NOT NULL, Marca VARCHAR(30) NOT NULL, Material VARCHAR(20) NOT NULL, Medidas VARCHAR(30) NOT NULL, Talla VARCHAR(15) NOT NULL);
CREATE TABLE Pregunta (ID INT PRIMARY KEY NOT NULL, Texto TEXT NOT NULL, Tiempo TIMESTAMP NOT NULL);
CREATE TABLE Mensajeria (ID INT PRIMARY KEY NOT NULL, Texto TEXT NOT NULL, Tiempo TIMESTAMP NOT NULL);
CREATE TABLE Devolucion (ID INT PRIMARY KEY NOT NULL, Valor INT NOT NULL, Medio TEXT NOT NULL);
CREATE TABLE Vender (Venta_id INT NOT NULL, MedioPago_id INT NOT NULL, Fecha DATE NOT NULL, PRIMARY KEY (Venta_id, MedioPago_id));
CREATE TABLE Poseer (Caracteristicas_id INT NOT NULL, Producto_id INT NOT NULL, Precio INT NOT NULL, PRIMARY KEY (Caracteristicas_id, Producto_id));
CREATE TABLE OfertarP (Producto_id INT NOT NULL, Oferta_id INT NOT NULL, Finicio DATE NOT NULL, Ffin DATE, PRIMARY KEY (Producto_id, Oferta_id, Finicio));
CREATE TABLE OfertarS (Servicio_id INT NOT NULL, Oferta_id INT NOT NULL, Finicio DATE NOT NULL, Ffin DATE, PRIMARY KEY (Servicio_id, Oferta_id, Finicio));
CREATE TABLE Comprar (Producto_id INT NOT NULL, Venta_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Devolucion_id INT, EstadoDevolucion VARCHAR(30), FechaDevolucion DATE, PRIMARY KEY (Producto_id, Venta_id, Cliente_id));
CREATE TABLE Contratar (Servicio_id INT NOT NULL, Venta_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, PRIMARY KEY (Servicio_id, Venta_id, Cliente_id));
CREATE TABLE PreguntarS (Pregunta_id INT NOT NULL, Servicio_id INT NOT NULL, Emprendedor_id VARCHAR(10) NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Fecha TIMESTAMP NOT NULL, PRIMARY KEY (Pregunta_id, Servicio_id, Emprendedor_id, Cliente_id, Fecha));
CREATE TABLE PreguntarP (Pregunta_id INT NOT NULL, Producto_id INT NOT NULL, Emprendedor_id VARCHAR(10) NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Fecha TIMESTAMP NOT NULL, PRIMARY KEY (Pregunta_id, Producto_id, Emprendedor_id, Cliente_id, Fecha));
CREATE TABLE ComunicarS (Servicio_id INT NOT NULL, Mensajeria_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Emprendedor_id VARCHAR(10) NOT NULL, Fecha TIMESTAMP NOT NULL, PRIMARY KEY (Servicio_id, Mensajeria_id, Cliente_id, Emprendedor_id, Fecha));
CREATE TABLE CalificarS (Servicio_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Calificacion_id INT NOT NULL, Venta_id INT NOT NULL, Fecha TIMESTAMP NOT NULL, PRIMARY KEY (Servicio_id, Cliente_id, Calificacion_id, Venta_id, Fecha));
CREATE TABLE ComunicarP (Producto_id INT NOT NULL, Mensajeria_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Emprendedor_id VARCHAR(10) NOT NULL, Fecha TIMESTAMP NOT NULL, PRIMARY KEY (Producto_id, Mensajeria_id, Cliente_id, Emprendedor_id, Fecha));
CREATE TABLE CalificarP (Producto_id INT NOT NULL, Calificacion_id INT NOT NULL, Venta_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Fecha TIMESTAMP NOT NULL, PRIMARY KEY (Producto_id, Calificacion_id, Venta_id, Cliente_id, Fecha));
CREATE TABLE OfrecerP (Producto_id INT NOT NULL, Emprendedor_id VARCHAR(10) NOT NULL, FechaInicio DATE NOT NULL, FechaFin DATE, Stock INT NOT NULL, PRIMARY KEY (Producto_id, Emprendedor_id));
CREATE TABLE OfrecerS (Servicio_id INT NOT NULL, Emprendedor_id VARCHAR(10) NOT NULL, FechaInicio DATE NOT NULL, FechaFin DATE, PRIMARY KEY (Servicio_id, Emprendedor_id));
CREATE TABLE Registrar (Cliente_id VARCHAR(10) NOT NULL, Direccion_id INT NOT NULL, PRIMARY KEY (Cliente_id, Direccion_id));
CREATE TABLE DesearP (Producto_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Lista VARCHAR(30), PRIMARY KEY (Producto_id, Cliente_id));
CREATE TABLE DesearS (Servicio_id INT NOT NULL, Cliente_id VARCHAR(10) NOT NULL, Lista VARCHAR(30), PRIMARY KEY (Servicio_id, Cliente_id));
CREATE TABLE TieneDirEmpresa (Empresa_ID VARCHAR(11) NOT NULL, Direccion_id INT NOT NULL, PRIMARY KEY (Empresa_ID, Direccion_id));
CREATE TABLE TieneDirE (Emprendedor_id VARCHAR(10) NOT NULL, Direccion_id INT NOT NULL, PRIMARY KEY (Emprendedor_id, Direccion_id));
CREATE TABLE Cotizacion (ID INT PRIMARY KEY, Cliente_id VARCHAR(10) NOT NULL, Fecha DATE NOT NULL DEFAULT CURRENT_DATE, Total INT, Estado VARCHAR(30) DEFAULT 'Solicitada', FOREIGN KEY (Cliente_id) REFERENCES Cliente(RUN));

ALTER TABLE OfrecerP ADD CONSTRAINT chk_ofrecerp_stock CHECK (Stock >= 0);
ALTER TABLE Envio ADD CONSTRAINT chk_envio_dimensiones CHECK (Peso >= 0 AND Altura >= 0 AND Ancho >= 0 AND Fondo >= 0);
ALTER TABLE Venta ADD CONSTRAINT chk_venta_total_bruto CHECK (Total >= ValorBruto);
ALTER TABLE Servicio ADD CONSTRAINT chk_servicio_precio CHECK (Precio >= 0);
ALTER TABLE Oferta ADD CONSTRAINT chk_oferta_precio CHECK (Precio >= 0);
ALTER TABLE Cliente ADD CONSTRAINT chk_cliente_fechanac CHECK (FechaNac >= '1940-01-01');
ALTER TABLE Emprendedor ADD CONSTRAINT chk_emprendedor_fechanac CHECK (FechaNac >= '1940-01-01');
ALTER TABLE Venta ADD CONSTRAINT chk_venta_estado CHECK (Estado IS NULL OR Estado IN ('En Preparación', 'Despachado', 'En reparto', 'Entregado', 'Recibido', 'Cancelada'));
ALTER TABLE Envio ADD CONSTRAINT chk_envio_fechas_1995 CHECK (FechaSalida >= '1995-01-01');
ALTER TABLE Cliente ADD CONSTRAINT chk_cliente_fechanac_no_futura CHECK (FechaNac <= CURRENT_DATE);
ALTER TABLE Venta ADD CONSTRAINT chk_venta_iva_19 CHECK (IVA = 19.00);